import * as React from 'react';
import * as CardSwipeStackPrimitive from '@exhuma/core';
import { cn } from '@/lib/utils';

export interface CardSwipeStackProps extends React.ComponentPropsWithoutRef<typeof CardSwipeStackPrimitive.CardSwipeStack> {
  className?: string;
}

export const CardSwipeStack = React.forwardRef<HTMLDivElement, CardSwipeStackProps>(
  ({ className, children, ...props }, ref) => (
    <CardSwipeStackPrimitive.CardSwipeStack
      ref={ref}
      className={cn(
        'relative flex items-center justify-center min-h-[420px] w-full',
        className
      )}
      {...props}
    >
      {children}
    </CardSwipeStackPrimitive.CardSwipeStack>
  )
);
CardSwipeStack.displayName = 'CardSwipeStack';

