import { Component, JSX, splitProps } from 'solid-js';
import * as CardSwipeStackPrimitive from '@exhuma/core';

export interface CardSwipeStackProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const CardSwipeStack: Component<CardSwipeStackProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <CardSwipeStackPrimitive.CardSwipeStack
      class={`relative flex items-center justify-center min-h-[420px] w-full ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </CardSwipeStackPrimitive.CardSwipeStack>
  );
};

