import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as CardSwipeStackPrimitive from '@exhuma/core';

export interface CardSwipeStackProps extends ViewProps {
  children?: React.ReactNode;
}

export function CardSwipeStack({ style, children, ...props }: CardSwipeStackProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

